import { Audio } from "expo-av";
import { applyAkbaAudioMode } from "./audioMode";

/**
 * Short cues for "AKBA is listening now" (rising) and "AKBA stopped
 * listening" (falling). Both files are generated by
 * scripts/sounds/make_earcons.py, so there is no third-party licence to track.
 *
 * A cue is feedback, never a dependency: every failure is swallowed and
 * reported once, so a broken sound can never take a voice session down with it.
 */

const LISTEN_START = require("../../assets/audio/akba-listen-start.wav");
const LISTEN_END = require("../../assets/audio/akba-listen-end.wav");

const VOLUME = 0.8;

let preloadPromise: Promise<void> | null = null;
let startSound: Audio.Sound | null = null;
let endSound: Audio.Sound | null = null;
let warned = false;

function warnOnce(error: unknown) {
  if (warned) return;
  warned = true;
  console.warn("[Earcons] Listen cue unavailable:", error);
}

/** Loads both cues once; later calls share the same promise. */
export function preloadEarcons(): Promise<void> {
  if (!preloadPromise) {
    preloadPromise = (async () => {
      try {
        const [start, end] = await Promise.all([
          Audio.Sound.createAsync(LISTEN_START, { shouldPlay: false, volume: VOLUME }),
          Audio.Sound.createAsync(LISTEN_END, { shouldPlay: false, volume: VOLUME }),
        ]);
        startSound = start.sound;
        endSound = end.sound;
      } catch (error) {
        warnOnce(error);
      }
    })();
  }
  return preloadPromise;
}

async function play(which: "start" | "end") {
  try {
    await preloadEarcons();
    const sound = which === "start" ? startSound : endSound;
    if (!sound) return;
    await applyAkbaAudioMode();
    await sound.replayAsync();
  } catch (error) {
    warnOnce(error);
  }
}

export function playListenStart(): Promise<void> {
  return play("start");
}

export function playListenEnd(): Promise<void> {
  return play("end");
}
